'use strict';
const $=id=>document.getElementById(id),canvas=$('world'),ctx=canvas.getContext('2d');
const chapters=[
 ['言灵发动','ACT I','举起有效凭证，让言灵短暂拨开认知的遮蔽。事物始终在那里，变化的是你看见的现实。'],
 ['脑内推演','ACT II','用灰色人偶复现进入房间的动作。一个词让自我开始模糊；及时停止联想，换一种说法。'],
 ['日常互动','ACT III','恶魔伯爵提出一场普通的邀约。选择回复策略，与麦斯威尔坐下来下一盘棋。'],
 ['恶作剧','ACT IV','一张不合时宜的规则，让经过的人都绕起了圈。伯爵也未能幸免。'],
 ['保护威尔逊','ACT V','伏案的侦探逐渐失去对周围的注意。阴影靠近，同伴必须打断尚未完成的认识。']
];
let art={},ready=false,scene=0,phase='idle',elapsed=0,time=0,last=0,paused=false,credential=false,danger=0,reveal=0,rule=false,actors=[],player,companion,earl,target=null,keys=new Set(),audio=null,musicTimer=null,musicStep=0;
const cycle=[0,1,2,2],dirs=['南','西南','西','西北','北','东北','东','东南'];
function person(kind,x,y){return {kind,x,y,dir:0,moving:false,pose:null};}
function say(text){$('speech').textContent=text;}
function record(text){$('record').textContent=text;}
function setPhase(next){phase=next;elapsed=0;target=null;}
function button(text,handler,style='',disabled=false){const b=document.createElement('button');b.textContent=text;b.className=style;b.disabled=disabled||!ready;b.onclick=()=>{handler();controls();};$('controls').append(b);}
function controls(){
 $('controls').replaceChildren();
 if(scene===0){button(credential?'◈ 有效凭证已佩戴':'◈ 佩戴有效凭证',()=>{credential=!credential;record(credential?'凭证与言灵建立联系。':'凭证已取下。');},'',phase==='casting');button('高举象征物 · 发动言灵',()=>{if(!credential){record('言灵没有响应。你需要一件有效凭证。');return;}setPhase('casting');player.pose='cast';say('sina ante ala e ijo.\nsina ante e nasin lukin mi taso.');record('你没有改变事物。你改变的，只是我看待它的方式。');},'primary',phase==='casting'||reveal>0);}
 if(scene===1){button('尝试使用危险词〔内容隐去〕',()=>{setPhase('danger');record('不是规则的结果。这个词本身正在侵蚀自我。');say('不对……这个词不能继续想下去。');},'danger',phase!=='idle');button('立刻停止联想',()=>{setPhase('stopped');danger=0;say('停下来。换一种说法。');record('联想已经中断，危险词不再参与推演。');},'',phase!=='danger');button('以「来访者」替换 · 推演入场',()=>{setPhase('simulate');danger=0;companion.x=320;companion.y=640;rule=true;say('来访者 → 经过门口 → 沿边缘行走');record('替代词已写入。灰色人偶开始复现进入时的动作。');},'primary',!['stopped','done'].includes(phase));}
 if(scene===2){button('同意邀约 · 坐下对弈',()=>{setPhase('seating');say('威尔逊：好，让我们开始。');record('回复策略：同意。双方走向棋桌。');},'primary',phase!=='invite');button('婉拒这次邀约',()=>{setPhase('declined');earl.pose=null;say('麦斯威尔：那么，改日再下。');record('回复策略：婉拒。邀约结束，可重演本幕。');},'',phase!=='invite');button('落下一枚棋子',()=>{setPhase('chessMove');record('威尔逊落子。麦斯威尔思索后回应。');},'',phase!=='chess');}
 if(scene===3){button('贴上那条恶作剧规则',()=>{setPhase('circling');rule=true;record('规则已贴上。经过的人开始绕圈。');say('威尔逊：应该……不会有什么大问题。');},'primary',phase!=='idle');}
 if(scene===4){button('开始伏案推理',()=>{setPhase('thinking');player.pose='think';record('线索正在脑内靠拢；具体连接不予展示。');say('威尔逊：只差一点……');},'primary',phase!=='idle');button('同伴靠近 · 立即打断',()=>{setPhase('interrupting');say('同伴：威尔逊！看着我！');record('同伴发现异状，立刻上前打断。');},'danger',phase!=='thinking');}
}
function select(index){scene=index;phase='idle';elapsed=0;danger=0;reveal=0;credential=false;rule=false;target=null;keys.clear();actors=[];player=person('wilson',590,580);actors.push(player);companion=null;earl=null;
 if(scene===0){companion=person('gray',825,460);actors.push(companion);say('');record('书房一切如常。至少，你所见的如此。');}
 if(scene===1){companion=person('gray',320,640);actors.push(companion);say('');record('复现场景已展开。灰色人偶等待你的规则。');}
 if(scene===2){earl=person('maxwell',745,500);earl.pose='invite';actors.push(earl);phase='invite';say('麦斯威尔：侦探，有兴趣陪我下一盘棋吗？');record('收到邀约：与麦斯威尔下国际象棋。');}
 if(scene===3){player.x=410;player.y=620;earl=person('maxwell',985,450);actors.push(earl);for(let i=0;i<4;i++)actors.push(person('gray',545+i*75,520+(i%2)*100));say('');record('公告板空着。这里暂时没有人转圈。');}
 if(scene===4){player.x=760;player.y=565;companion=person('gray',410,610);actors.push(companion);say('');record('同伴在房间另一侧。威尔逊准备开始推理。');}
 $('title').textContent=chapters[scene][0];$('chapter').textContent=chapters[scene][1];$('intro').textContent=chapters[scene][2];$('stage-label').textContent=`第${['一','二','三','四','五'][scene]}幕 / ${chapters[scene][0]}`;document.querySelectorAll('#scenes button').forEach((b,i)=>b.setAttribute('aria-selected',String(i===scene)));controls();hud();}
chapters.forEach((c,i)=>{const b=document.createElement('button');b.innerHTML=`<small>0${i+1}</small>${c[0]}`;b.onclick=()=>select(i);$('scenes').append(b);});
$('reset').onclick=()=>select(scene);
$('pause').onclick=()=>{paused=!paused;keys.clear();$('pause').textContent=paused?'继续画面':'暂停画面';$('next-frame').disabled=!paused;};
$('next-frame').onclick=()=>{update(1/6);draw();};
function focusedInput(e){return /INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName);}
window.addEventListener('keydown',e=>{if(focusedInput(e))return;if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){keys.add(e.key);target=null;e.preventDefault();}});
window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();last=0;});
canvas.addEventListener('pointerdown',e=>{canvas.focus();const r=canvas.getBoundingClientRect();target={x:Math.max(270,Math.min(1000,(e.clientX-r.left)*1200/r.width)),y:Math.max(370,Math.min(705,(e.clientY-r.top)*800/r.height))};});
function direction(dx,dy){return (Math.round(Math.atan2(-dx,dy)/(Math.PI/4))+8)%8;}
function move(p,x,y,dt,speed=120){const dx=x-p.x,dy=y-p.y;if(Math.hypot(dx,dy)<4){p.moving=false;return true;}p.dir=direction(dx,dy);const angle=p.dir*Math.PI/4,step=Math.min(speed*dt,Math.hypot(dx,dy));p.x-=Math.sin(angle)*step;p.y+=Math.cos(angle)*step;p.moving=true;return false;}
function free(){return !player.pose&&!['seating','chess','chessMove','thinking','interrupting','recovering'].includes(phase);}
function update(dt){time+=dt;elapsed+=dt;actors.forEach(p=>p.moving=false);
 if(free()) {const dx=Number(keys.has('d')||keys.has('ArrowRight'))-Number(keys.has('a')||keys.has('ArrowLeft')),dy=Number(keys.has('s')||keys.has('ArrowDown'))-Number(keys.has('w')||keys.has('ArrowUp'));if(dx||dy){const len=Math.hypot(dx,dy);player.x+=dx/len*130*dt;player.y+=dy/len*130*dt;player.dir=direction(dx,dy);player.moving=true;}else if(target&&move(player,target.x,target.y,dt,130))target=null;player.x=Math.max(270,Math.min(1000,player.x));player.y=Math.max(370,Math.min(705,player.y));}
 if(scene===0){if(phase==='casting'&&elapsed>1.2){setPhase('revealed');player.pose=null;reveal=7;record('凭证生效。七秒内可看清灰色来客身后的异常投影。');controls();}if(reveal>0){reveal=Math.max(0,reveal-dt);if(reveal===0){setPhase('idle');say('视线重新蒙上薄雾。');record('客观事物没有改变，短暂的现实辨识结束。');controls();}}}
 if(scene===1){if(phase==='danger')danger=Math.min(.95,danger+dt*.12);if(phase==='simulate'){const points=[[410,595],[410,430],[650,430],[850,560]],i=Math.min(3,Math.floor(elapsed/2.3));move(companion,...points[i],dt,105);if(elapsed>10){setPhase('done');record('推演完成。人偶沿替代规则行动，未再触及危险词。');controls();}}}
 if(scene===2){if(phase==='seating'){earl.pose=null;const a=move(player,445,555,dt),b=move(earl,655,555,dt);if(a&&b){setPhase('chess');say('麦斯威尔：请。你执白。');record('邀约成立，双方已入座。点击落子观看三帧动作。');controls();}}if(phase==='chessMove'&&elapsed>2.4){setPhase('chess');say('麦斯威尔：轮到你了。');record('双方各走了一步。棋局继续。');controls();}}
 if(scene===3){if(rule){actors.filter(p=>p.kind==='gray').forEach((p,i)=>{const a=elapsed*1.3+i*Math.PI/2;move(p,660+Math.cos(a)*125,545+Math.sin(a)*68,dt,160);});}if(phase==='circling'){if(elapsed>3){const a=(elapsed-3)*1.3;move(earl,660+Math.cos(a)*125,545+Math.sin(a)*68,dt,175);}if(elapsed>4&&elapsed<4.2)say('麦斯威尔：……我为什么也在转？');if(elapsed>11){setPhase('investigating');say('麦斯威尔：等等。是那张纸。');record('伯爵察觉来源，走向规则。');}}if(phase==='investigating'&&move(earl,700,415,dt,135)){setPhase('ripping');earl.pose='rip';}if(phase==='ripping'&&elapsed>.8){rule=false;}if(phase==='ripping'&&elapsed>1.8){setPhase('done');say('麦斯威尔：这是什么垃圾规则！给我适可而止！');record('规则被撕毁并废除。所有人停止绕圈。');controls();}}
 if(scene===4){if(phase==='thinking')danger=Math.min(.94,danger+dt*.095);if(phase==='interrupting'){danger=Math.min(.94,danger+dt*.02);if(move(companion,865,565,dt,190)){setPhase('recovering');companion.pose='interrupt';record('同伴伸手打断，尚未成立的连接停止延伸。');}}if(phase==='recovering'){danger=Math.max(0,danger-dt*.65);if(elapsed>1.7){setPhase('done');player.pose=null;companion.pose=null;danger=0;say('威尔逊：……我听见了。谢谢。');record('威尔逊恢复对周围的注意。危险认识没有成立。');controls();}}}
 hud();}
function hud(){let label='现实辨识',value=reveal/7,note=credential?'凭证有效 · 可以发动言灵':'需要有效凭证才能拨开认知遮蔽';if(scene===1){label='自我失稳';value=danger;note=phase==='danger'?'立即停止联想。危险来自词汇本身。':rule?'替代词：来访者 · 推演不触及异常名称':'复现场景 · 只操纵灰色人偶';}if(scene===2){label='邀约状态';value=['chess','chessMove'].includes(phase)?1:0;note=['chess','chessMove'].includes(phase)?'双方已同意 · 正在对弈':'等待玩家选择回复策略';}if(scene===3){label='规则效力';value=rule?1:0;note=rule?'规则正在影响房间内的来客':'规则尚未生效或已被废除';}if(scene===4){label='危险认识';value=danger;note=phase==='done'?'连接已中断 · 注意恢复':'只呈现伏案、阴影和打断，不展示线索连接';}$('meter-label').textContent=label;$('meter-value').textContent=Math.round(value*100)+'%';$('meter').style.width=value*100+'%';$('meter').style.background=danger>.2?'#b67c6a':'#c0a56c';$('note').textContent=note;$('layer').textContent=scene===1?'脑内推演':reveal>0?'现实显露 · '+reveal.toFixed(1)+'s':'主观世界';$('loading').textContent=ready?(player.moving?'朝'+dirs[player.dir]+'行走':'点击地面 / 八向移动'):'正在装入手绘素材…';}
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('素材载入失败：'+src));im.src='assets/'+src;});}
// White atlas backgrounds are keyed only where connected to the outer border.
// This preserves enclosed white eyes, shirts and paper; source art is never rewritten.
function atlas(im,cols,rows,keyWhite=false){const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const g=c.getContext('2d',{willReadFrequently:true});g.drawImage(im,0,0);const data=g.getImageData(0,0,c.width,c.height),d=data.data,w=c.width,h=c.height;
 if(keyWhite){const visited=new Uint8Array(w*h),queue=new Int32Array(w*h);let head=0,tail=0;const add=p=>{if(p<0||p>=w*h||visited[p])return;visited[p]=1;const n=p*4;if(d[n]>226&&d[n+1]>226&&d[n+2]>226){queue[tail++]=p;d[n+3]=0;}};for(let x=0;x<w;x++){add(x);add((h-1)*w+x);}for(let y=0;y<h;y++){add(y*w);add(y*w+w-1);}while(head<tail){const p=queue[head++];if(p%w)add(p-1);if(p%w<w-1)add(p+1);add(p-w);add(p+w);}g.putImageData(data,0,0);}
 const frames=[];for(let row=0;row<rows;row++){frames[row]=[];for(let col=0;col<cols;col++){let left=Math.round(col*w/cols),right=Math.round((col+1)*w/cols),top=Math.round(row*h/rows),bottom=Math.round((row+1)*h/rows);if(cols===6&&row===2){const edges=[0,280,532,820,1030,1286,1536];left=Math.round(edges[col]*w/1536);right=Math.round(edges[col+1]*w/1536);}let x0=right,y0=bottom,x1=left,y1=top;for(let y=top;y<bottom;y++)for(let x=left;x<right;x++){if(d[(y*w+x)*4+3]>100){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}}frames[row][col]={x:x0,y:y0,w:x1-x0+1,h:y1-y0+1};}}return {image:c,frames};}
function sprite(sheet,row,col,x,y,height){const a=art[sheet],f=a.frames[row][col],width=height*f.w/f.h;ctx.drawImage(a.image,f.x,f.y,f.w,f.h,x-width/2,y-height,width,height);}
function renderPerson(p){ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(p.x,p.y-3,27,8,0,0,Math.PI*2);ctx.fill();const f=cycle[Math.floor(time*6)%4];if(p.pose){let row=0,start=0,height=145,frame=f;if(p.pose==='cast'){frame=cycle[Math.min(3,Math.floor(elapsed*3))];height=165;}if(p.pose==='think'){start=3;height=150;frame=phase==='recovering'?2:Math.floor(time*2)%2;}if(p.pose==='rip'){row=1;frame=phase==='done'?2:cycle[Math.min(3,Math.floor(elapsed*2.5))];height=165;}if(p.pose==='invite'){row=1;start=3;height=165;}if(p.pose==='interrupt'){row=2;start=3;height=145;frame=cycle[Math.min(3,Math.floor(elapsed*3))];}sprite('actions',row,start+frame,p.x,p.y,height);}else sprite(p.kind,p.moving?f:1,p.dir,p.x,p.y,p.kind==='maxwell'?165:145);}
function shadow(x,y,strength){ctx.save();ctx.globalAlpha=strength;ctx.translate(x,y);ctx.fillStyle='#07080bdd';for(let i=0;i<7;i++){ctx.beginPath();ctx.moveTo(-60+i*19,10);ctx.bezierCurveTo(-110+i*27,-65,-125+i*33,-140+Math.sin(i)*30,-90+i*30,-215-Math.cos(i)*35);ctx.bezierCurveTo(-55+i*19,-130,-20+i*9,-50,60-i*18,10);ctx.fill();}ctx.restore();}
function positionSpeech(){const p=scene===2?earl:scene===4&&['interrupting','recovering'].includes(phase)?companion:scene===3&&phase!=='idle'?earl:player;if(!p)return;
 const bubble=$('speech');bubble.style.top=Math.max(8,(p.y-250)/8)+'%';bubble.style.left=Math.max(3,Math.min(27,p.x/12-35))+'%';bubble.style.right='auto';bubble.style.width='70%';}
function draw(){positionSpeech();ctx.clearRect(0,0,1200,800);if(!ready)return;ctx.drawImage(art.bg,0,0,1200,800);if(scene===1){ctx.fillStyle='#152e32aa';ctx.fillRect(0,0,1200,800);ctx.strokeStyle='#c3d4bf44';ctx.setLineDash([4,12]);ctx.beginPath();ctx.moveTo(320,640);ctx.lineTo(410,595);ctx.lineTo(410,430);ctx.lineTo(650,430);ctx.lineTo(850,560);ctx.stroke();ctx.setLineDash([]);}
 if(reveal>0){ctx.fillStyle='#788d8622';ctx.fillRect(0,0,1200,800);shadow(companion.x,companion.y,.9);ctx.strokeStyle='#d2c39a88';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(player.x,player.y,95,38,0,0,Math.PI*2);ctx.stroke();}
 if(scene===3&&rule){ctx.save();ctx.translate(690,370);ctx.rotate(-.09);ctx.fillStyle='#d2c19b';ctx.fillRect(-17,-23,34,46);ctx.strokeStyle='#544331';for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(-11,-13+i*7);ctx.lineTo(10-i%3*4,-13+i*7);ctx.stroke();}ctx.restore();}
 if(scene===4&&danger>0){shadow(player.x-82,player.y,danger*.9);shadow(player.x+65,player.y+15,danger);}
 if(scene===2&&['chess','chessMove'].includes(phase)){const f=phase==='chess'?0:cycle[Math.min(3,Math.floor(elapsed/0.6))];sprite('actions',2,f,550,575,180);}else [...actors].sort((a,b)=>a.y-b.y).forEach(renderPerson);
 if(target&&free()){ctx.strokeStyle='#d0c39977';ctx.beginPath();ctx.ellipse(target.x,target.y,12,5,0,0,Math.PI*2);ctx.stroke();}
 if(danger>0){const v=ctx.createRadialGradient(player.x,player.y-65,60,player.x,player.y-65,570);v.addColorStop(0,'#09090b00');v.addColorStop(1,`rgba(10,4,13,${danger*.92})`);ctx.fillStyle=v;ctx.fillRect(0,0,1200,800);}
 // Candle flicker is lighting only; every character action is atlas playback.
 ctx.fillStyle=`rgba(218,172,92,${.014+Math.sin(time*3)*.007})`;ctx.fillRect(0,0,1200,800);$('frame').textContent='SPRITE '+(Math.floor(time*6)%4+1)+'/4 · '+(Math.floor(time*6)%4===3?'停顿帧':'动作帧');}
function tick(now){const dt=last?Math.min((now-last)/1000,.05):0;last=now;if(ready&&!paused)update(dt);draw();requestAnimationFrame(tick);}
$('music').onclick=async()=>{if(musicTimer){clearInterval(musicTimer);musicTimer=null;await audio.suspend();$('music').textContent='♫ 开启配乐';$('music').setAttribute('aria-pressed','false');return;}audio??=new AudioContext();await audio.resume();const melody=[57,60,64,63,57,55,59,56,57,60,67,64,63,59,56,52];const note=()=>{const t=audio.currentTime;for(const [midi,type,volume,duration] of [[melody[musicStep%16],'square',.025,.29],[musicStep%8<4?45:40,'triangle',.05,.38]]){const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+duration);}musicStep++;};note();musicTimer=setInterval(note,420);$('music').textContent='♫ 关闭配乐';$('music').setAttribute('aria-pressed','true');};
select(0);requestAnimationFrame(tick);
Promise.all(['manor-stage.png','wilson-walk.png','maxwell-walk.png','gray-walk.png','story-actions.png'].map(loadImage)).then(([bg,w,m,g,a])=>{art={bg,wilson:atlas(w,8,3),maxwell:atlas(m,8,3,true),gray:atlas(g,8,3,true),actions:atlas(a,6,3)};ready=true;controls();hud();}).catch(error=>{$('loading').textContent=error.message;record('请通过本地服务器打开此页，并确认 assets 目录完整。');});
